def vram_by_phase(path):
    """Per-phase used-MiB (median) from vram.txt sections '== <phase> ...'."""
    if not path.exists():
        return {}
    out, phase, values = {}, None, []
    for ln in path.read_text().splitlines():
        ln = ln.strip()
        if ln.startswith("=="):
            if phase:
                out[phase] = statistics.median(values) if values else None
            m = re.match(r"==\s*(.+)$", ln)
            phase = m.group(1).strip() if m else ""
            values = []
        else:
            values.extend(int(x) for x in re.findall(r"\b(\d+) MiB,", ln))
    if phase and values:
        out[phase] = statistics.median(values)
    return {k: v for k, v in out.items() if v is not None}

